draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // draw arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30 + 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 + 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // draw legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 130);
  ctx.stroke();

  // draw backpack
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 15, H/2 + 50, 30, 20);

  // draw nervous face
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 10 + 5 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 10, H/2 - 20, 2, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H/2 - 20, 2, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 30);
  ctx.lineTo(W/2 + 15, H/2 - 30);
  ctx.stroke();

  ctx.restore();
}
